"""Layer 15 MLP down_proj, component 4749.

What it does: a quantity-expression detector. It dips negative on the unit or measure word
right after an amount, as in "two years", "ten percent", "three times", "a few days", "5 km",
and on comparison words right after an amount ("two less", "3 times more"). The dip is
largest after a spelled-out count (two..ten), medium after a vague amount ("a", "a few",
"several", "many", "one", "half"), and smaller after a digit. A number that follows a
framing word ("at least 10", "about 5", "by 3", "was 2") gets a weak dip. Everything else
stays near zero.

The values are fitted by hand to the component's activations on training text, using
word classes a reader already knows (count words, vague quantity words, time and measure
nouns). The actual activations also depend on the surrounding sentence in ways a word list
cannot capture, so this explains only a small share of the variance.
"""

READS = ()

COUNT_WORDS = {
    "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven",
    "twelve", "fifteen", "sixteen", "twenty", "thirty", "forty", "fifty", "hundred",
    "thousand",
}
VAGUE_WORDS = {"a", "an", "few", "several", "many", "some", "couple", "one", "half", "twice", "more"}
DIGITS = set("0123456789")
NUMBER_WORDS = COUNT_WORDS | VAGUE_WORDS
UNITS = {
    "year", "years", "month", "months", "week", "weeks", "day", "days", "hour", "hours",
    "minute", "minutes", "second", "seconds", "decade", "decades", "percent", "%", "times",
    "fold", "miles", "mile", "km", "kilometres", "kilometers", "meters", "metres", "cent",
    "orders", "points", "levels", "magnitude", "factor", "degrees", "step", "steps",
    "dollars", "inch", "inches", "feet", "million", "billion",
}
COMPARISONS = {"less", "more", "higher", "lower", "larger", "smaller", "faster", "slower",
               "than", "behind", "ahead", "later", "ago", "over", "bigger", "longer", "shorter"}
FRAMING = {"least", "approximately", "about", "only", "by", "nearly", "almost", "just",
           "around", "than", "was", "were", "is", "up"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    words = [_word(prefix.token_strings[i]) for i in range(max(0, t - 2), t + 1)]
    word = words[-1]
    same_doc = t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    prev = words[-2] if same_doc else ""
    prev2 = words[-3] if same_doc and t > 1 and prefix.document_ids[t - 2] == prefix.document_ids[t] else ""

    if word in UNITS and prev in COUNT_WORDS:
        value = -4.5
    elif word in UNITS and prev in VAGUE_WORDS:
        value = -2.8
    elif word in UNITS and prev in DIGITS:
        value = -1.9
    elif word in COMPARISONS and (prev in NUMBER_WORDS or prev in DIGITS):
        value = -0.7
    elif (word in DIGITS or word in COUNT_WORDS) and (prev in FRAMING or prev2 in FRAMING):
        value = -0.3
    else:
        value = 0.0
    return carry, float(value)

"""Negation-contrast component (layers.15 MLP down_proj, direction 4755).

In plain terms: this component is nearly silent. Its activation is a small,
dense, sign-mixed signal (about +/-0.3 at most positions) with no per-token
pattern, and the model barely uses it. The one construction it reacts to
consistently is the contrast "not only X" / "not just X" (and "nicht nur",
"не только", "non solo", "nie tylko"):
  * the "only"/"just" right after a negator is positive, about +1.4;
  * the word after that (the item being contrasted) is mildly negative, about -0.3;
  * every other position is predicted as 0.
"""
from collections.abc import Mapping

READS = ()

NEGATORS = {"not", "nicht", "не", "non", "nie"}
FOCUS = {"only", "just", "merely", "nur", "solo", "только", "tylko"}


def word(s):
    return s.strip().lower()


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    ids = prefix.document_ids

    def back(k):
        # the word k tokens back, or None across a document boundary
        if t - k < 0 or ids[t - k] != ids[t]:
            return None
        return word(prefix.token_strings[t - k])

    if back(1) in NEGATORS and word(prefix.token_strings[t]) in FOCUS:
        return carry, 1.4
    if back(2) in NEGATORS and back(1) in FOCUS:
        return carry, -0.3
    return carry, 0.0

"""Negative where the text is about to open a quoted string or a JSON value.

Component p-82af68dd@100000/layers.15.mlp.down_proj:4782 goes strongly negative on the
colon that closes a JSON key when a quoted string or an object is coming next
(`"name": "`, `"arguments": {`), most of all inside an assistant <tool_call> block.
Inside a tool call, the JSON punctuation and key names are negative too, while the
values inside the quotes stay near zero. Outside tool calls, print/log/format-call
words (`printf`, `console.log`, `echo`, `#include`, `require`), which are followed by
a string literal, are weakly negative. Everything else is near zero.

The program reads only the current token, whether a <tool_call> block is open, and
the key before a colon. It needs no other component.
"""

READS = ()

# JSON keys whose values are usually quoted text or objects (strong negative).
TEXT_KEYS = {
    "name", "arguments", "command", "path", "description", "message", "thought",
    "parameters", "properties", "text", "content", "query", "url", "title", "code",
}
# JSON keys whose values are usually numbers, booleans or short labels (weak).
NUM_KEYS = {
    "line", "column", "start", "end", "timeout", "id", "value", "type", "version",
    "status", "count", "enum", "required", "index", "size",
}
# Inside a <tool_call>, the JSON punctuation and key names, with typical values.
CALL_TOKENS = {
    ' "': -4.0, '",': -7.0, '{"': -7.0, ' {"': -8.0,
    "arguments": -12.0, "command": -8.0, "name": -6.0, "description": -8.0,
}
# Words for printing, logging, formatting or including, usually followed by a string.
PRINT_WORDS = {
    "print", "printf", "println", "echo", "Printf", "Println", "Errorf", "Sprintf",
    "log", "info", "warn", "error", "debug", "cout", "include", "require",
}


def step(carry, prefix, upstream):
    """carry: whether a <tool_call> block is open at this token."""
    inside = bool(carry)
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        inside = False  # a new document starts: no tool call is open
    t = prefix.token_strings[-1]
    if t == "<tool_call>":
        inside = True
    elif t == "</tool_call>":
        inside = False

    if t == '":':
        key = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
        if inside:
            value = -18.0
        elif key in TEXT_KEYS or key.endswith(("_str", "_range", "_text")):
            value = -14.0
        elif key in NUM_KEYS:
            value = -2.0
        else:
            value = -8.0
    elif inside:
        value = CALL_TOKENS.get(t, 0.0)
    elif t.lstrip(".#\t") in PRINT_WORDS:
        value = -3.0
    else:
        value = 0.0
    return inside, value

"""p-82af68dd@100000 layers.15.mlp.down_proj:4788: a weak, diffuse feature.

Plain-terms summary. The component's activation is high on bare symbols (a single digit
or letter used as a number, variable or label: "2", "x", "C"), and highest when such a
symbol follows a math mark ("+", "_", "^", "{", "×", "="). It is also higher on plain
words and on any token that already occurred earlier in the same document, and lower on
punctuation, spaces and function words ("of", "the", "and"). At a document's first token it
is about zero. Token identity alone explains almost nothing; these context rules explain
a few percent of the variance (eval: 3.3% variance explained, r = 0.19; the rules fit on
2k training rows give about 4% held out).

The program keeps, per document, the set of tokens and of token pairs seen so far. It
reads only the current token and the one before it.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

MATH_MARKS = set("=+-*/^_{}\\$×−√<>|≤≥≠≈")
FUNCTION_WORDS = {
    "the", "of", "and", "is", "a", "an", "to", "in", "for", "that", "with", "be", "on",
    "as", "was", "by", "or", "are", "it",
}


def is_symbol(text: str) -> bool:
    """A bare digit or single letter: a number, variable or label."""
    s = text.strip()
    return len(s) == 1 and (s.isdigit() or s.isalpha())


def has_math_mark(text: str) -> bool:
    return any(ch in MATH_MARKS for ch in text)


def base_value(text: str, prev_text: str) -> float:
    """What the token's own kind and the token before it add, before repetition."""
    s = text.strip()
    value = -0.08  # intercept
    if is_symbol(text):
        value += 0.11
        if has_math_mark(prev_text):
            value += 0.45  # a symbol right after an operator or subscript mark
    elif s == "":
        value -= 0.08  # whitespace-only token
    elif not any(ch.isalnum() for ch in s):
        value -= 0.10  # punctuation or operator
    elif s.lower() in FUNCTION_WORDS:
        value += 0.0
    else:
        value += 0.15  # a plain word or subword
        if has_math_mark(prev_text):
            value += 0.08
    return value


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_ids[-1]
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry["doc"] != doc:
        # A new document: its first token is near zero; start its memory empty.
        carry = {"doc": doc, "seen": set(), "pairs": set(), "prev": None, "prev_text": ""}
        value = 0.0
    else:
        value = base_value(text, carry["prev_text"])
        if token in carry["seen"]:
            value += 0.23  # the token already occurred earlier in this document
        if (carry["prev"], token) in carry["pairs"]:
            value += 0.14  # the same pair of tokens occurred earlier
    carry["pairs"].add((carry["prev"], token))
    carry["seen"].add(token)
    carry["prev"], carry["prev_text"] = token, text
    return carry, float(value)

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:4799 (layer 15 MLP hidden unit 4799).

Its activation is small and diffuse (std 0.34) and mostly unpredictable from the prefix. The
most negative values (below -3) fall on words that name people or groups of people, for
example "people", "woman", "kids", "those", "they", "students", at about 2.5 times the base
rate. This program predicts a slightly negative value on those words and a value near the
component's mean elsewhere.
"""

from functools import cache

import wordnet

READS = ()

PERSON_WORDS = {
    "people", "person", "they", "we", "you", "those", "everyone", "someone", "students",
    "kids", "children", "women", "men", "woman", "man", "adults", "others", "everybody",
    "individuals", "humans", "human", "workers", "families", "parents", "teachers",
    "companies", "citizens", "friends", "patients",
}


@cache
def is_person_word(word):
    word = word.strip().lower()
    if not word.isascii() or not word.isalpha():
        return False
    if word in PERSON_WORDS:
        return True
    return wordnet.is_a(word, "person") or wordnet.is_a(word, "group")


def step(carry, prefix, upstream):
    token = prefix.token_strings[prefix.position]
    return carry, (-0.04 if is_person_word(token) else -0.024)
